TESTS=('test_provider_comparison.py',)

class Refused(RuntimeError): pass

def sha(data): return hashlib.sha256(data).hexdigest()

def safe_rel(value):
    p=PurePosixPath(value)
    if (not value or p.is_absolute() or '..' in p.parts or str(p)!=value or '\\' in value
            or any(x in {'.private','.state','runs','workflows','diagnostics','backups'} or x.startswith('.env') for x in p.parts)):
        raise Refused('Unsafe tool path in manifest/payload')
    return p

def unpack():
    raw=zlib.decompress(base64.b85decode(PAYLOAD.encode('ascii')))
    if sha(raw)!=PAYLOAD_SHA256: raise Refused('Embedded payload digest mismatch')
    data=json.loads(raw)
    for name,row in data.items():
        safe_rel(name); body=row['content'].encode('utf-8')
        if sha(body)!=row['new_sha256']: raise Refused('Invalid payload file digest: '+name)
        if name.endswith('.py'): compile(row['content'],name,'exec')
    return data

def manifest(target):
    path=target/'MANIFEST.sha256'
    if path.is_symlink() or not path.is_file(): raise Refused('Missing/linked tool manifest')
    out={}
    for line in path.read_text(encoding='utf-8').splitlines():
        m=re.fullmatch(r'([a-f0-9]{64})  (.+)',line)
        if not m: raise Refused('Invalid tool manifest row')
        digest,name=m.groups(); safe_rel(name)
        if name=='MANIFEST.sha256' or name in out: raise Refused('Duplicate/self manifest entry')
        p=target/name
        parts=PurePosixPath(name).parts
        if any((target/Path(*parts[:i])).is_symlink() for i in range(1,len(parts)+1)): raise Refused('Linked tool path: '+name)
        if not p.is_file() or sha(p.read_bytes())!=digest: raise Refused('Current tool manifest mismatch: '+name)
        out[name]=digest
    return out

def inspect(target,data):
    actual={}
    for name,row in data.items():
        p=target/name
        if p.is_symlink(): raise Refused('Linked update target: '+name)
        actual[name]=sha(p.read_bytes()) if p.is_file() else None
    if all(actual[n]==r['new_sha256'] for n,r in data.items()): return 'already_installed'
    conflicts=[n for n,r in data.items() if actual[n] not in r['accepted_old_sha256']+[r['new_sha256']]]
    if conflicts: raise Refused('Tool delta conflicts; no files changed: '+', '.join(conflicts))
    return 'ready'

def atomic_write(path,data,mode=0o600):
    path.parent.mkdir(parents=True,exist_ok=True)
    fd,name=tempfile.mkstemp(prefix='.'+path.name+'.patch-',dir=path.parent)
    try:
        with os.fdopen(fd,'wb') as stream:
            stream.write(data); stream.flush(); os.fsync(stream.fileno())
        os.chmod(name,mode & 0o777); os.replace(name,path)
    finally:
        if os.path.exists(name): os.unlink(name)

def run_tests(stage,log):
    base_env=dict(os.environ); base_env['PYTHONDONTWRITEBYTECODE']='1'; base_env['PYTHON_BIN']=sys.executable
    scratch_root=stage/'.selftest-tmp'; scratch_root.mkdir(mode=0o700)
    with log.open('wb') as output:
        for shell in sorted(stage.glob('*.sh')):
            r=subprocess.run(['bash','-n',str(shell)],stdout=output,stderr=subprocess.STDOUT,timeout=20,env=base_env,cwd=stage)
            if r.returncode: raise Refused('Shell syntax failure; nothing installed')
        for name in TESTS:
            print('[OFFLINE SELFTEST]',name,flush=True)
            scratch=scratch_root/Path(name).stem
            if scratch.exists(): shutil.rmtree(scratch)
            scratch.mkdir(mode=0o700)
            env=dict(base_env)
            for key in ('TMPDIR','TMP','TEMP'): env[key]=str(scratch)
            try:
                r=subprocess.run([sys.executable,'-I','-B',str(stage/'tests'/name)],cwd=stage,env=env,
                                 stdout=output,stderr=subprocess.STDOUT,timeout=120)
            finally:
                shutil.rmtree(scratch,ignore_errors=True)
            output.flush()
            if r.returncode: raise Refused('Offline/loopback selftest failed: '+name+'; nothing installed')

def apply(target,data,tracked):
    tag=datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%d-%H%M%S-%f')
    maintenance=target/'.maintenance'
    if maintenance.is_symlink(): raise Refused('Linked maintenance directory')
    maintenance.mkdir(exist_ok=True,mode=0o700)
    if (target/'backups').is_symlink(): raise Refused('Linked backup directory')
    with tempfile.TemporaryDirectory(prefix='shadow-ab-stage-',dir=maintenance) as td:
        stage=Path(td)
        for name in tracked:
            dest=stage/name; dest.parent.mkdir(parents=True,exist_ok=True); shutil.copyfile(target/name,dest)
        for name,row in data.items():
            dest=stage/name; dest.parent.mkdir(parents=True,exist_ok=True); dest.write_text(row['content'],encoding='utf-8')
        names=sorted(set(tracked)|set(data))
        digest_text=''.join(sha((stage/n).read_bytes())+'  '+n+'\n' for n in names)
        (stage/'MANIFEST.sha256').write_text(digest_text,encoding='utf-8')
        log=stage/'offline-selftest.log'
        try: run_tests(stage,log)
        except (Refused,subprocess.TimeoutExpired) as exc:
            diagnostic=target/'backups'/('shadow-ab-selftest-'+tag+'.log')
            if log.is_file(): atomic_write(diagnostic,log.read_bytes())
            raise Refused(str(exc)+'; diagnostic: '+str(diagnostic)) from None
        if manifest(target)!=tracked or inspect(target,data)!='ready': raise Refused('Tool files changed while staging; nothing installed')
        backup=target/'backups'/('shadow-ab-'+tag); backup.mkdir(parents=True,exist_ok=False)
        before={}; modes={}
        for name in list(data)+['MANIFEST.sha256']:
            p=target/name; before[name]=p.read_bytes() if p.is_file() else None
            modes[name]=stat.S_IMODE(p.stat().st_mode) if p.is_file() else 0o600
            if before[name] is not None: atomic_write(backup/name,before[name],modes[name])
        atomic_write(backup/'new-files.json',json.dumps([n for n,b in before.items() if b is None],indent=2).encode())
        atomic_write(backup/'offline-selftest.log',log.read_bytes())
        installed=[]
        try:
            for name in data:
                atomic_write(target/name,(stage/name).read_bytes(),modes[name]); installed.append(name)
            atomic_write(target/'MANIFEST.sha256',digest_text.encode(),modes['MANIFEST.sha256']); installed.append('MANIFEST.sha256')
            manifest(target)
        except BaseException:
            rollback_errors=[]
            for name in reversed(installed):
                try:
                    if before[name] is None: (target/name).unlink(missing_ok=True)
                    else: atomic_write(target/name,before[name],modes[name])
                except Exception: rollback_errors.append(name)
            if rollback_errors: print('[ROLLBACK INCOMPLETE]',', '.join(rollback_errors),'backup:',backup,file=sys.stderr)
            raise
        print('[APPLIED]',PATCH_ID,flush=True); print('[BACKUP]',backup,flush=True)
        print('[NO LIVE TEST RUN] Run the existing Shadow A/B command after install.',flush=True)

def main():
    if sys.version_info<(3,10): raise Refused('Python 3.10 or later is required by the existing harness')
    if sys.platform!='linux': raise Refused('Apply this server-side harness update on Linux')
    import fcntl
    ap=argparse.ArgumentParser(description=__doc__)
    ap.add_argument('--target',default=DEFAULT_TARGET,help='Existing harness root; default: '+DEFAULT_TARGET)
    g=ap.add_mutually_exclusive_group(required=True); g.add_argument('--check',action='store_true'); g.add_argument('--apply',action='store_true')
    args=ap.parse_args(); os.umask(0o077)
    given=Path(args.target)
    if given.is_symlink(): raise Refused('Target must not be a symlink')
    target=given.resolve(strict=True)
    if not target.is_dir() or not (target/'bench.py').is_file(): raise Refused('Target is not the existing harness directory')
    data=unpack()
    with contextlib.ExitStack() as stack:
        for name in ('.verified-workflow.lock','.benchmark.lock'):
            p=target/name
            if p.is_symlink(): raise Refused('Linked lock file')
            stream=stack.enter_context(p.open('a'))
            try: fcntl.flock(stream.fileno(),fcntl.LOCK_EX|fcntl.LOCK_NB)
            except BlockingIOError: raise Refused('An existing workflow/benchmark owns the lock; no update performed') from None
        tracked=manifest(target); status=inspect(target,data)
        print('[HARNESS_ROOT]',target,flush=True)
        print('[CHECK]',status,'reviewed payload files:',len(data),flush=True)
        for name in sorted(data): print('  '+name,flush=True)
        if args.check or status=='already_installed': return 0
        apply(target,data,tracked)
    return 0

if __name__=='__main__':
    try: raise SystemExit(main())
    except (Refused,OSError,ValueError,subprocess.TimeoutExpired) as exc:
        print('[REFUSED]',str(exc),file=sys.stderr); raise SystemExit(1)
